<script setup lang="ts">import { ref } from 'vue'; import { useRoute } from 'vue-router'; import { CheckCircle, ShieldAlert } from 'lucide-vue-next'; import { verifyService, type VerificationResult } from '../../services/verifyService'; import BaseInput from '../../components/ui/BaseInput.vue'; import BaseButton from '../../components/ui/BaseButton.vue'; import BaseAlert from '../../components/ui/BaseAlert.vue'; import { formatDate } from '../../utils/formatDate'; const route = useRoute(); const code = ref(String(route.params.codigo || '')); const result = ref<VerificationResult>(); const error = ref(''); const file = ref<File>(); const integrity = ref<{ integro: boolean }>(); const loading = ref(false); async function verify() { error.value = ''; result.value = undefined; if (!code.value.trim()) return; loading.value = true; try { result.value = await verifyService.verify(code.value.trim()) } catch { error.value = 'Código não encontrado.' } finally { loading.value = false } } async function checkIntegrity() { if (!file.value) return; try { integrity.value = await verifyService.integrity(code.value, file.value) } catch { error.value = 'Não foi possível verificar a integridade.' } }</script>
<template><div><section class="card"><div class="mb-6 text-center"><h1 class="text-2xl font-bold">Verificar documento</h1><p class="muted mt-1">Consulte a autenticidade de um documento aprovado.</p></div><form class="flex flex-col gap-3 sm:flex-row sm:items-end" @submit.prevent="verify"><div class="flex-1"><BaseInput id="verification-code" v-model="code" label="Código de verificação" placeholder="XXXX-XXXX" /></div><BaseButton type="submit" :loading="loading">Consultar</BaseButton></form><BaseAlert v-if="error" type="error" :message="error" class="mt-5" /><div v-if="result" class="mt-6 rounded-xl border border-green-200 bg-green-50 p-5"><div class="flex items-center gap-3 text-green-800"><CheckCircle class="h-8 w-8" /><div><h2 class="text-lg font-bold">Documento Válido</h2><p class="text-sm">O código foi encontrado no registro oficial.</p></div></div><dl class="mt-5 grid gap-3 text-sm sm:grid-cols-2"><div><dt class="text-green-800/70">Template</dt><dd class="font-semibold">{{ result.template }}</dd></div><div><dt class="text-green-800/70">Validador</dt><dd class="font-semibold">{{ result.nomeValidador }}</dd></div><div><dt class="text-green-800/70">Data de aprovação</dt><dd class="font-semibold">{{ formatDate(result.dataAprovacao) }}</dd></div><div><dt class="text-green-800/70">Data de envio</dt><dd class="font-semibold">{{ formatDate(result.dataEnvio) }}</dd></div></dl></div></section><section class="card mt-6"><div class="flex items-center gap-3"><ShieldAlert class="h-6 w-6 text-primary" /><div><h2 class="font-bold">Verificar integridade do arquivo</h2><p class="muted">Compare o PDF recebido com o arquivo original.</p></div></div><div class="mt-4 flex flex-wrap items-end gap-3"><label class="text-sm font-medium">Arquivo PDF<input type="file" accept="application/pdf,.pdf" class="mt-1 block rounded border p-2" @change="file = ($event.target as HTMLInputElement).files?.[0]" /></label><BaseButton variant="secondary" :disabled="!file || !code" @click="checkIntegrity">Verificar integridade</BaseButton></div><BaseAlert v-if="integrity" :type="integrity.integro ? 'success' : 'warning'" :message="integrity.integro ? 'Integridade verificada: o arquivo não foi alterado.' : 'Atenção: o arquivo foi alterado ou é diferente do original.'" class="mt-4" /></section></div></template>
